SELECT s.id, s.symbol, s.latest_price, s.stop_loss, s.take_profit, s.risk_reward_ratio, s.atr_percent, ROUND((s.latest_price - s.stop_loss) / s.latest_price * 100, 4) AS stop_pct, ROUND((s.take_profit - s.latest_price) / s.latest_price * 100, 4) AS tp_pct, ROUND(6 * s.atr_percent, 4) AS six_atr_pct FROM trade_signal s WHERE s.id IN (156723,159408,165412,167668,171589,176710) ORDER BY s.id